adolf-nossberger-hutte-at.message:
Selhalo po 3 pokusech: celá chata: Adolf-Noßberger-Hütte, AT | poslední chyba: Timeout while waiting for: 
      Array.from(document.querySelectorAll(
        '.cdk-overlay-container mat-option, .cdk-overlay-container .mat-mdc-option, [role="option"]'
      )).some(el => {
        const txt = (el.innerText || el.textContent || '').trim().toLowerCase();
        const visible = !!(el.offsetWidth || el.offsetHeight || el.getClientRects().length);
        return visible && txt.length > 0 && txt.includes("adolf-noßberger");
      })

